import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface ChipProps extends React.HTMLAttributes<HTMLSpanElement> {}


const styles = stylex.create({
  chip: {
    fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
    fontSize: {
      default: "0.6875rem",
      [mq.phone]: "0.8125rem",
    },
    fontWeight: 500,
    color: raster.gray,
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: "color-mix(in srgb, currentColor 35%, transparent)",
    paddingBlock: {
      default: "0.1875rem",
      [mq.phone]: "0.75rem",
    },
    paddingInline: {
      default: "0.4375rem",
      [mq.phone]: "0.875rem",
    },
    lineHeight: 1,
    borderRadius: {
      default: raster.radiusSm,
      [mq.phone]: 0,
    },
    display: {
      default: null,
      [mq.phone]: "inline-flex",
    },
    alignItems: {
      default: null,
      [mq.phone]: "center",
    },
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
  },
});

/** Mono identifier with a 1px mixed border. */
export const Chip = React.forwardRef<HTMLSpanElement, ChipProps>(function Chip(
  { className, style, ...props },
  ref,
) {
  const sx = rs(["rs-chip", className], styles.chip);
  return <span ref={ref} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

/* ── chip: generated from packages/react/src/components/chip.tsx ── */
.rs-chip{font-family:ui-monospace, SFMono-Regular, Menlo, monospace;font-size:0.6875rem;font-weight:500;color:var(--text-secondary);border-width:1px;border-style:solid;border-color:color-mix(in srgb, currentColor 35%, transparent);padding-block:0.1875rem;padding-inline:0.4375rem;line-height:1;border-radius:var(--radius-sm)}
@media (max-width: 640px){.rs-chip{font-size:0.8125rem;padding-block:0.75rem;padding-inline:0.875rem;border-radius:0;display:inline-flex;align-items:center;min-height:var(--hit)}}
